    pub fn sanitized(&self) -> Self {
        BridgeConfig {
            ring_target_ms: if self.ring_target_ms.is_finite() { self.ring_target_ms.clamp(0.0, 200.0) } else { 0.0 },
            loopback_enabled: self.loopback_enabled,
        }
    }
}

